import csv


def answer() -> int:
    # Relevant lineage and descendants traced from genealogy_trees.txt.
    children = {
        "Przemysław Kurczab": [
            "Liwia Maligłówka", "Julianna Paściak", "Julita Kucharz", "Alan Wocial"
        ],
        "Liwia Maligłówka": ["Adam Gałach"],
        "Adam Gałach": ["Andrzej Pietrek", "Juliusz Dębosz", "Rozalia Grzesiek"],
        "Juliusz Dębosz": ["Kazimierz Kiliszek", "Dawid Majtyka"],
        "Julita Kucharz": ["Filip Krysta", "Kazimierz Kaziród", "Franciszek Grabias"],
        "Franciszek Grabias": ["Marianna Pędzik"],
        "Alan Wocial": ["Albert Wydmuch", "Julita Duczek", "Tola Radko"],
        "Albert Wydmuch": ["Michał Wawrzyńczyk"],
        "Julita Duczek": ["Fabian Drygała"],
        "Tola Radko": ["Kamila Bodzak"],
    }
    parents = {child: parent for parent, descendants in children.items() for child in descendants}
    ancestor = "Dawid Majtyka"
    for _ in range(4):
        ancestor = parents[ancestor]
    qualifying = {
        child for child in children[ancestor]
        if sum(len(children.get(grandchild, [])) for grandchild in children.get(child, [])) > 1
    }
    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as f:
        balances = {
            f"{row['first_name']} {row['last_name']}": int(row["account_balance"])
            for row in csv.DictReader(f)
        }
    return sum(balances[name] for name in qualifying)


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
